diff --git a/daemon/controllers/thermalcontroller.cpp b/daemon/controllers/thermalcontroller.cpp
new file mode 100644
index 000000000..2ec076ca6
--- /dev/null
+++ b/daemon/controllers/thermalcontroller.cpp
@@ -0,0 +1,117 @@
+/*
+ *   SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ *   SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "thermalcontroller.h"
+
+#include <QDir>
+#include <QFile>
+
+#include <powerdevil_debug.h>
+
+#include <chrono>
+#include <optional>
+
+using namespace std::chrono_literals;
+using namespace Qt::StringLiterals;
+
+inline constexpr QLatin1StringView THERMAL_SYSFS_PATH("/sys/class/thermal/");
+
+// Warn this many millidegrees before the critical trip point, and stop warning this far below the warning temperature
+static constexpr int s_criticalMargin = 5000;
+static constexpr int s_hysteresis = 5000;
+
+static std::optional<int> readMillidegrees(const QString &path)
+{
+    QFile file(path);
+    if (!file.open(QIODevice::ReadOnly)) {
+        return std::nullopt;
+    }
+    bool ok = false;
+    const int value = file.readAll().trimmed().toInt(&ok);
+    if (!ok) {
+        return std::nullopt;
+    }
+    return value;
+}
+
+static QString readType(const QString &path)
+{
+    QFile file(path);
+    if (!file.open(QIODevice::ReadOnly)) {
+        return QString();
+    }
+    return QString::fromLatin1(file.readAll().trimmed());
+}
+
+ThermalController::ThermalController()
+    : QObject()
+{
+    const QStringList zoneNames = QDir(THERMAL_SYSFS_PATH).entryList({u"thermal_zone*"_s}, QDir::Dirs | QDir::NoDotAndDotDot);
+    for (const QString &zoneName : zoneNames) {
+        const QString zonePath = THERMAL_SYSFS_PATH + zoneName + u'/';
+        std::optional<int> criticalTemperature;
+        std::optional<int> hotTemperature;
+
+        const QStringList tripTypes = QDir(zonePath).entryList({u"trip_point_*_type"_s}, QDir::Files);
+        for (const QString &tripType : tripTypes) {
+            const QString type = readType(zonePath + tripType);
+            if (type != "critical"_L1 && type != "hot"_L1) {
+                continue;
+            }
+            const auto temperature = readMillidegrees(zonePath + QStringView(tripType).chopped(4) + u"temp");
+            if (!temperature || *temperature <= 0) {
+                continue;
+            }
+            (type == "critical"_L1 ? criticalTemperature : hotTemperature) = *temperature;
+        }
+
+        if (!criticalTemperature) {
+            continue;
+        }
+        int warningTemperature = *criticalTemperature - s_criticalMargin;
+        if (hotTemperature && *hotTemperature < warningTemperature) {
+            warningTemperature = *hotTemperature;
+        }
+        qCDebug(POWERDEVIL) << "Watching" << zoneName << "critical temperature" << *criticalTemperature << "warning at" << warningTemperature;
+        m_zones.append({zonePath + u"temp", warningTemperature});
+    }
+
+    if (m_zones.isEmpty()) {
+        return;
+    }
+
+    connect(&m_timer, &QTimer::timeout, this, &ThermalController::checkTemperatures);
+    m_timer.start(5s);
+    checkTemperatures();
+}
+
+bool ThermalController::isOverheating() const
+{
+    return m_isOverheating;
+}
+
+void ThermalController::checkTemperatures()
+{
+    bool overheating = false;
+    for (const ThermalZone &zone : std::as_const(m_zones)) {
+        const auto temperature = readMillidegrees(zone.temperaturePath);
+        if (!temperature) {
+            continue;
+        }
+        const int threshold = m_isOverheating ? zone.warningTemperature - s_hysteresis : zone.warningTemperature;
+        if (*temperature >= threshold) {
+            overheating = true;
+            break;
+        }
+    }
+
+    if (overheating != m_isOverheating) {
+        m_isOverheating = overheating;
+        Q_EMIT overheatingChanged(m_isOverheating);
+    }
+}
+
+#include "moc_thermalcontroller.cpp"
