+ *
+ *   SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#pragma once
+
+#include <QList>
+#include <QObject>
+#include <QString>
+#include <QTimer>
+
+#include "powerdevilcore_export.h"
+
+class POWERDEVILCORE_EXPORT ThermalController : public QObject
+{
+    Q_OBJECT
+public:
+    ThermalController();
+
+    /**
+     * @returns whether any thermal zone is close to the temperature at which the kernel shuts the system down
+     */
+    bool isOverheating() const;
+
+Q_SIGNALS:
+    void overheatingChanged(bool overheating);
+
+private:
+    struct ThermalZone {
+        QString temperaturePath;
+        int warningTemperature; // millidegrees Celsius
+    };
+
+    void checkTemperatures();
+
+    QList<ThermalZone> m_zones;
+    QTimer m_timer;
+    bool m_isOverheating = false;
+};
diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 33badced8..b55cf0363 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -126,6 +126,9 @@ void Core::onControllersReady()
     connect(m_batteryController.get(), &BatteryController::batteryRemainingTimeChanged, this, &Core::onBatteryRemainingTimeChanged);
     connect(m_batteryController.get(), &BatteryController::smoothedBatteryRemainingTimeChanged, this, &Core::onSmoothedBatteryRemainingTimeChanged);
     connect(m_lidController.get(), &LidController::lidClosedChanged, this, &Core::onLidClosedChanged);
+    m_thermalController = std::make_unique<ThermalController>();
+    connect(m_thermalController.get(), &ThermalController::overheatingChanged, this, &Core::onOverheatingChanged);
+    onOverheatingChanged(m_thermalController->isOverheating());
     connect(m_suspendController.get(), &SuspendController::aboutToSuspend, this, &Core::onAboutToSuspend);
     connect(KIdleTime::instance(), &KIdleTime::timeoutReached, this, &Core::onKIdleTimeoutReached);
     connect(KIdleTime::instance(), &KIdleTime::resumingFromIdle, this, &Core::onResumingFromIdle);
@@ -862,6 +865,27 @@ void Core::onKIdleTimeoutReached(int identifier, int msec)
     }
 }

+void Core::onOverheatingChanged(bool overheating)
+{
+    if (!overheating) {
+        if (m_overheatingNotification) {
+            m_overheatingNotification->close();
+        }
+        return;
+    }
+    if (m_overheatingNotification) {
+        return;
+    }
+
+    m_overheatingNotification = new KNotification(QStringLiteral("overheating"), KNotification::Persistent, nullptr);
+    m_overheatingNotification->setComponentName(QStringLiteral("powerdevil"));
+    m_overheatingNotification->setTitle(i18nc("@title:notifications", "Computer Overheating"));
+    m_overheatingNotification->setText(i18n(
+        "The computer is close to its critical temperature and will turn off if it gets any hotter. Save your work and make sure its vents are not blocked."));
+    m_overheatingNotification->setUrgency(KNotification::CriticalUrgency);
+    m_overheatingNotification->sendEvent();
+}
+
 void Core::onLidClosedChanged(bool closed)
 {
     Q_EMIT lidClosedChanged(closed);
